const cut=ctx.createBiquadFilter();cut.type='lowpass';cut.frequency.setValueAtTime(ease(p.cutoff,110,18500),t);cut.Q.value=.65+p.res*14;const out=ctx.createGain();out.gain.value=.5;const amp=ctx.createGain();cut.connect(amp);amp.connect(out);out.connect(this.fx.input);
