 const o=ctx.createOscillator(),g=ctx.createGain();let det=i===0?0:((i%2?-1:1)*(Math.ceil(i/2)*3.7)*p.detune*3.4);let wf=p.wave==='PWM'?'square':'sawtooth';if(p.wave==='FM'||p.wave==='FORMANT')wf='sine';if(p.wave==='SHAPE')wf='triangle';if(p.wave==='FEEDBACK')wf='sawtooth';if(p.wave==='SYNC')wf='sawtooth';o.type=wf;o.frequency.setValueAtTime(f*Math.pow(2,(p.tune-.5)*.2),t);o.detune.value=det;
 g.gain.value=i===0?1:((p.mix||.5)/(layers-1))*1.25;
 if(p.wave==='FORMANT'){const pw=wave(ctx,'VOCAL',p.shape);o.setPeriodicWave(pw)}
