 if(p.wave==='FM'){const mod=ctx.createOscillator(),mg=ctx.createGain();mod.frequency.value=f*2;mg.gain.value=f*p.shape*2;mod.connect(mg);mg.connect(o.frequency);mod.start(t);mod.stop(end+.02)}
